import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

/**
 * INT-102 fixture seed: the exact, committed, sanitized raw evidence the browser
 * end-to-end run exercises.
 *
 * Everything here is read from fixtures already committed under `tests/fixtures/`
 * (the golden dataset generated by `packages/evaluation` plus the sanitized TestRail
 * records). No external source is contacted, and no credential, token, or restricted
 * payload is present. TestRail records are re-pointed at the golden-dataset ticket keys
 * exactly the way the FL Titling product configuration maps its reference fields
 * (`custom_jira_references` / `custom_github_automation`), mirroring `INT-101`.
 */

const FIXTURE_ROOT = new URL("../../fixtures/", import.meta.url);

export const E2E_TENANT_ID = "solera";
export const E2E_PRODUCT_ID = "fl-titling";

/** Requirement that is fully covered by GitHub automation and a TestRail manual case. */
export const COVERED_TICKET = "FLT-2001";
/** Requirements whose second Jira revision disagrees, producing reviewable conflicts. */
export const CONFLICTING_TICKETS = ["FLT-2023", "FLT-2024"];

export const TESTRAIL_REFERENCE_MAPPING = {
  jiraReferenceField: "custom_jira_references",
  githubAutomationReferenceField: "custom_github_automation",
};

function readFixture(relativePath) {
  return JSON.parse(readFileSync(fileURLToPath(new URL(relativePath, FIXTURE_ROOT)), "utf8"));
}

function ticketRecords(ticketKey, fileNames) {
  return fileNames.map((fileName) =>
    readFixture(`golden-dataset/tickets/${ticketKey}/${fileName}`));
}

function testRailRecords() {
  const caseFixture = readFixture("testrail/case-traceability.json").case;
  const executionFixture = readFixture("testrail/execution-normalization.json");

  const suite = {
    ...caseFixture,
    sourceId: "12",
    contentType: "testrail.suite",
    contentHash: "sha256-fixture-testrail-suite-12",
    payload: {
      id: 12,
      name: "FL Titling sanitized regression suite",
      updated_on: 1789056000,
    },
  };
  const manualCase = {
    ...caseFixture,
    payload: {
      ...caseFixture.payload,
      suite_id: 12,
      custom_jira_references: [COVERED_TICKET],
      custom_github_automation: ["test:github:5000"],
    },
  };
  const run = executionFixture.run;
  const result = {
    ...executionFixture.result,
    payload: { ...executionFixture.result.payload, case_id: 1202 },
  };

  return [suite, manualCase, run, result];
}

/**
 * Builds the deterministic raw evidence set seeded into the harness API: one fully
 * covered Jira story with GitHub + TestRail evidence, and two stories whose second Jira
 * revision conflicts with the first (the conflict review flow under test).
 */
export function buildSeedRecords() {
  return [
    ...ticketRecords(COVERED_TICKET, ["jira.raw.json", "github-5000.raw.json"]),
    ...CONFLICTING_TICKETS.flatMap((ticketKey, index) =>
      ticketRecords(ticketKey, [
        "jira.raw.json",
        "jira.revision-2.raw.json",
        `github-53${22 + index}.raw.json`,
      ])),
    ...testRailRecords(),
  ];
}

/**
 * Connector health derived from the records actually seeded, so the dashboard's
 * Connector Health view reflects this run instead of invented numbers. Only credential
 * *references* are reported - never a credential value.
 */
export function buildConnectorHealth(records) {
  const credentialRefs = {
    jira: "secret://fixtures/jira",
    github: "secret://fixtures/github",
    testrail: "secret://fixtures/testrail",
  };

  return Object.entries(credentialRefs).map(([source, credentialRef]) => {
    const sourceRecords = records.filter((record) => record.source === source);
    const lastObservedAt = sourceRecords
      .map((record) => record.observedAt)
      .sort()
      .at(-1) ?? null;

    return {
      component: `connector:${source}`,
      health: {
        status: "healthy",
        records: sourceRecords.length,
        failures: 0,
        lastSyncAt: lastObservedAt,
        lastSuccessfulSyncAt: lastObservedAt,
        credentialRef,
        message:
          "Fixture-backed connector (INT-102 end-to-end harness); no live source was contacted.",
      },
    };
  });
}
